   $pdo->beginTransaction();$st=$pdo->prepare('SELECT * FROM absensi WHERE sesi_id=? AND siswa_id=? FOR UPDATE');$st->execute([$sesiId,$sid]);$ex=$st->fetch();
   if($ex){$old=$ex['status'];$up=$pdo->prepare("UPDATE absensi SET status=?,sumber_terakhir='VERIFIKASI',status_verifikasi='valid',diverifikasi_oleh=?,diverifikasi_at=NOW(),keterangan=? WHERE id=?");$up->execute([$new,user_id(),$note,$ex['id']]);if($old!==$new){$ch=$pdo->prepare('INSERT INTO absensi_perubahan (absensi_id,status_lama,status_baru,alasan,diubah_oleh) VALUES (?,?,?,?,?)');$ch->execute([$ex['id'],$old,$new,$auditReason,user_id()]);}$id=(int)$ex['id'];}
   else{$ins=$pdo->prepare("INSERT INTO absensi (sesi_id,siswa_id,status,waktu_scan,scan_oleh,metode_awal,sumber_terakhir,status_verifikasi,diverifikasi_oleh,diverifikasi_at,keterangan) VALUES (?,?,?,NULL,?, 'MANUAL','VERIFIKASI','valid',?,NOW(),?)");$ins->execute([$sesiId,$sid,$new,user_id(),user_id(),$note]);$id=(int)$pdo->lastInsertId();$ch=$pdo->prepare('INSERT INTO absensi_perubahan (absensi_id,status_lama,status_baru,alasan,diubah_oleh) VALUES (?,?,?,?,?)');$ch->execute([$id,null,$new,$auditReason,user_id()]);}
