$where=["s.status='aktif'"];$params=[$sesi['tahun_pelajaran_id']];if($cari!==''){$where[]='(s.nis LIKE ? OR s.nisn LIKE ? OR s.nama LIKE ? OR s.kode_qr LIKE ?)';$q="%$cari%";array_push($params,$q,$q,$q,$q);}if($kelasId>0){$where[]='mk.id=?';$params[]=$kelasId;}if($filter==='belum')$where[]='a.id IS NULL';elseif($filter!=='semua'){$where[]='a.status=?';$params[]=$filter;}$whereSql='WHERE '.implode(' AND ',$where);
