$st=$pdo->prepare("SELECT s.id,s.nis,s.nisn,s.nama,mk.nama nama_kelas,sk.nomor_urut,a.id absensi_id,a.status absensi_status,a.waktu_scan,a.waktu_pulang,a.metode_awal,a.status_verifikasi,a.keterangan FROM siswa s LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 WHERE sk2.siswa_id=s.id AND sk2.tahun_pelajaran_id=? AND sk2.status='aktif' ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id LEFT JOIN absensi a ON a.sesi_id=? AND a.siswa_id=s.id $whereSql ORDER BY COALESCE(mk.urutan,9999),COALESCE(sk.nomor_urut,9999),s.nama LIMIT $perPage OFFSET $offset");$st->execute(array_merge([$sesi['tahun_pelajaran_id'],$sesiId],array_slice($params,1)));$rows=$st->fetchAll();
