)?>"><?=$code?></button></form><?php endforeach;?></div><?php elseif($sesi['status']==='ditutup'&&$can):?><a class="btn btn-secondary btn-sm btn-icon-sm" title="Koreksi absensi" aria-label="Koreksi absensi" href="<?=BASE_URL?>absensi/manual.php?sesi_id=<?=$sesiId?>&siswa_id=<?=(int)$r['id']?>&mode=koreksi"><i class="bi bi-pencil-square" aria-hidden="true"></i></a><?php endif;?><?php if($stt && user_role()==='admin' && $sesi['status']!=='ditutup'):?><form method="post" action="<?=BASE_URL?>absensi/hapus_record.php" style="display:inline" onsubmit="return confirm('Hapus record kehadiran siswa ini? Sesi tetap dipertahankan.')"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$r['absensi_id']?>"><input type="hidden" name="sesi_id" value="<?=$sesiId?>"><button class="btn btn-danger btn-sm btn-icon-sm" type="submit" title="Hapus record" aria-label="Hapus record"><i class="bi bi-trash3" aria-hidden="true"></i></button></form><?php endif;?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="8" class="empty-state">Tidak ada data.</td></tr><?php endif;?></tbody></table></div></div>

<div id="reasonModal" class="reason-modal" hidden aria-hidden="true"><div class="reason-modal-backdrop"></div><div class="reason-modal-card" role="dialog" aria-modal="true" aria-labelledby="reasonModalTitle"><div class="reason-modal-head"><div><h3 id="reasonModalTitle">Verifikasi Manual</h3><p id="reasonModalText"></p></div><button type="button" class="reason-modal-close" id="reasonCancel" aria-label="Tutup">&times;</button></div><div id="reasonOptions" class="reason-options"></div><label id="reasonExtraWrap" class="reason-extra" hidden>Keterangan tambahan <span id="reasonExtraMark" style="color:#dc2626;display:none">*</span><textarea id="reasonInput" class="form-control" rows="3" maxlength="500" placeholder="Tulis keterangan tambahan..."></textarea><small id="reasonExtraHelp">Opsional. Isi jika perlu penjelasan tambahan.</small></label><div class="reason-modal-actions"><button type="button" class="btn btn-secondary" id="reasonCancel2">Batal</button><button type="button" class="btn btn-primary" id="reasonSubmit">Simpan Verifikasi</button></div></div></div>
<script>document.addEventListener('DOMContentLoaded',function(){(function(){let f=null,selected='';const m=document.getElementById('reasonModal'),i=document.getElementById('reasonInput'),t=document.getElementById('reasonModalText'),o=document.getElementById('reasonOptions'),extra=document.getElementById('reasonExtraWrap'),mark=document.getElementById('reasonExtraMark'),help=document.getElementById('reasonExtraHelp');const choices={H:['Tidak membawa kartu','QR tidak terbaca','Lupa melakukan scan','Kendala perangkat','Lainnya'],T:['Terlambat masuk sekolah','Terlambat karena keperluan sekolah','Kendala perjalanan','Lainnya'],I:['Ada kepentingan','Izin','Dijemput orang tua/wali','Keperluan keluarga','Keperluan pribadi','Keperluan sekolah','Lainnya'],S:['Kurang enak badan','Demam','Berobat','Kondisi kesehatan lainnya','Lainnya']};function c(){m.hidden=true;m.setAttribute('aria-hidden','true');f=null;selected='';i.value='';o.innerHTML='';extra.hidden=true;mark.style.display='none'}function render(s){o.innerHTML='';(choices[s]||[]).forEach(v=>{const b=document.createElement('button');b.type='button';b.className='reason-option';b.textContent=v;b.dataset.value=v;b.addEventListener('click',function(){selected=v;o.querySelectorAll('.reason-option').forEach(x=>x.classList.remove('active'));b.classList.add('active');extra.hidden=false;const other=v==='Lainnya';mark.style.display=other?'inline':'none';help.textContent=other?'Wajib diisi jika memilih Lainnya.':'Opsional. Isi jika perlu penjelasan tambahan.';i.placeholder=other?'Wajib: jelaskan alasan...':'Tambahkan keterangan jika diperlukan...';if(other)setTimeout(()=>i.focus(),30)});o.appendChild(b)})}document.querySelectorAll('.verify-status-form').forEach(x=>x.addEventListener('submit',function(e){const s=x.dataset.status;if(s==='A')return;e.preventDefault();f=x;selected='';i.value='';t.textContent=s==='H'?'Siswa dinyatakan hadir secara manual. Pilih alasan tidak tercatat melalui QR.':(s==='T'?'Pilih keterangan keterlambatan.':(s==='S'?'Pilih kondisi sakit.':'Pilih alasan izin.'));render(s);m.hidden=false;m.setAttribute('aria-hidden','false')}));document.getElementById('reasonSubmit').addEventListener('click',function(){if(!selected){t.textContent='Silakan pilih salah satu alasan terlebih dahulu.';return}const v=i.value.trim();if(selected==='Lainnya'&&!v){i.focus();return}const reason=selected+(v?' — '+v:'');f.querySelector('input[name=alasan]').value=reason;f.submit()});document.getElementById('reasonCancel').addEventListener('click',c);document.getElementById('reasonCancel2').addEventListener('click',c);document.querySelector('.reason-modal-backdrop').addEventListener('click',c);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!m.hidden)c()})})();});</script><style>.reason-modal{position:fixed;inset:0;z-index:2000;display:flex;align-items:center;justify-content:center;padding:20px}.reason-modal[hidden]{display:none}.reason-modal-backdrop{position:absolute;inset:0;background:rgba(15,23,42,.48)}.reason-modal-card{position:relative;width:min(560px,100%);background:#fff;border-radius:16px;box-shadow:0 24px 70px rgba(15,23,42,.25);padding:22px}.reason-modal-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:16px}.reason-modal-head h3{margin:0;font-size:19px}.reason-modal-head p{margin:5px 0 0;color:#64748b;font-size:13px}.reason-modal-close{border:0;background:transparent;font-size:28px;line-height:1;color:#64748b;cursor:pointer}.reason-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.reason-option{border:1px solid #cbd5e1;background:#fff;border-radius:10px;padding:11px 12px;text-align:left;font-weight:600;color:#334155;cursor:pointer}.reason-option:hover{border-color:#64748b}.reason-option.active{background:#eff6ff;border-color:#2563eb;color:#1d4ed8;box-shadow:0 0 0 2px rgba(37,99,235,.08)}.reason-extra{display:block;margin-top:16px}.reason-extra textarea{margin-top:7px;resize:vertical}.reason-extra small{display:block;margin-top:5px;color:#64748b}.reason-modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}@media(max-width:600px){.reason-options{grid-template-columns:1fr}}</style>
