<script>
(function(){
  'use strict';
  var tableBody = document.querySelector('.attendance-detail-module .data-table tbody');
  var summaryGrid = document.querySelector('.attendance-detail-module .dashboard-grid');
  var module = document.querySelector('.attendance-detail-module');
  if (!tableBody || !module || !window.SPLASMA_REALTIME || !window.fetch) return;
  var sessionStatus = <?= json_encode((string)$sesi['status'], JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;
  var finalized = <?= absensi_is_finalized($pdo, $sesiId) ? 'true' : 'false' ?>;
  if (sessionStatus !== 'aktif' || finalized) return;
  var busy = false;
  function hasActiveInteraction(){
    var active = document.activeElement;
    return !!(module.querySelector('.reason-modal:not([hidden])') || (active && (active.matches('input,textarea,select') || active.closest('.verify-status-form'))));
  }
  function refreshAttendance(){
    if (busy || document.visibilityState === 'hidden' || hasActiveInteraction()) return;
    busy = true;
    var url = new URL(window.location.href);
    url.searchParams.set('_realtime', String(Date.now()));
    fetch(url.toString(), {credentials:'same-origin', headers:{'X-Requested-With':'XMLHttpRequest','Cache-Control':'no-cache'}})
      .then(function(response){ if(!response.ok) throw new Error('refresh failed'); return response.text(); })
      .then(function(html){
        var doc = new DOMParser().parseFromString(html, 'text/html');
        var nextBody = doc.querySelector('.attendance-detail-module .data-table tbody');
        var nextSummary = doc.querySelector('.attendance-detail-module .dashboard-grid');
        if (!nextBody || !tableBody.isConnected) return;
        tableBody.innerHTML = nextBody.innerHTML;
        if (summaryGrid && nextSummary) summaryGrid.innerHTML = nextSummary.innerHTML;
      })
      .catch(function(){ /* Keep current content during temporary network errors. */ })
      .finally(function(){ busy = false; });
  }
  window.SPLASMA_REALTIME.register('attendance-verification-list', refreshAttendance, 10000);
  window.SPLASMA_REALTIME.start('attendance-verification-list');
})();
</script>
<?php require_once __DIR__.'/../layouts/footer.php';?>
